<?php require_once __DIR__.'/../includes/bootstrap.php';require_role(['member']);verify_csrf();$id=(int)($_POST['id']??0);$uid=(int)current_user()['id'];$s=$conn->prepare("UPDATE reservations SET status='cancelled',updated_at=NOW() WHERE id=? AND user_id=? AND status IN('pending','approved')");$s->bind_param('ii',$id,$uid);$s->execute();if($s->affected_rows){log_activity($conn,$uid,'reservation_cancelled','Reservation #'.$id);flash('success','Reservation cancelled.');}else flash('error','Reservation cannot be cancelled in its current status.');redirect('reservations.php');
